def process_menu_data(menu_data):
    """Process the menu data and create concise summaries for ALL projects"""
    
    for item in menu_data:
        if "submenu" in item:
            for subitem in item["submenu"]:
                if "pageSummary" in subitem:
                    # Always replace with concise summary to ensure consistency
                    subitem["pageSummary"] = create_concise_summary(subitem)
    
    return menu_data

def main():
    # Read the original menu.json file
    with open("data/menu.json", "r", encoding="utf-8") as f:
        menu_data = json.load(f)
    
    # Process the data to create concise summaries for ALL projects
    resume_data = process_menu_data(menu_data)
    
    # Write the processed data to resume.json
    with open("resume/resume.json", "w", encoding="utf-8") as f:
        json.dump(resume_data, f, indent=2, ensure_ascii=False)
    
    print("Successfully created resume/resume.json with ALL projects and concise summaries")

if __name__ == "__main__":
    main() 